// Signs the request for overdue loans. Secret: n8n Variable LENDLOOP_INBOUND_SECRET
// (same value as Convex env N8N_INBOUND_SECRET).
const crypto = require('crypto');
const secret = $vars.LENDLOOP_INBOUND_SECRET;
if (!secret) throw new Error('LENDLOOP_INBOUND_SECRET is not set');

const path = '/n8n/overdue-loans';
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'v1=' + crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.GET.${path}.`)
  .digest('hex');
return [{ json: { timestamp, signature } }];

// Convex signs its response too: only email loans this data really came from.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;
const secret = $vars.LENDLOOP_INBOUND_SECRET;
const res = $input.first().json;
const headers = res.headers || {};
const raw = typeof res.body === 'string' ? res.body : null;
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'] || '';

if (raw === null) throw new Error('Expected a text response body (Response Format: Text)');
if (!timestamp || !signature.startsWith('v1=')) throw new Error('Convex response is not signed');
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > MAX_SKEW_SECONDS) {
  throw new Error('Convex response signature is stale');
}
const expected = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.RESPONSE./n8n/overdue-loans.${raw}`)
  .digest();
const given = Buffer.from(signature.slice(3), 'hex');
if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) {
  throw new Error('Convex response signature does not match');
}

// One item per overdue loan; no loans means the run simply ends here.
return JSON.parse(raw).loans.map((loan) => ({ json: loan }));

const loan = $json;
const days = loan.daysOverdue === 1 ? '1 day' : `${loan.daysOverdue} days`;
return {
  json: {
    loanId: loan.loanId,
    reminderDate: loan.reminderDate,
    idempotencyKey: loan.idempotencyKey,
    to: loan.borrower.email,
    subject: `Reminder: please return the ${loan.toolName}`,
    text: `Hi ${loan.borrower.firstName},\n\nThe ${loan.toolName} you borrowed from ${loan.ownerFirstName} was due back on ${loan.dueDate} (${days} ago). Please arrange to return it soon.\n${loan.appUrl}\n\n- LendLoop`,
  },
};

const r = $('Build reminder').item.json;
return {
  json: {
    loanId: r.loanId,
    reminderDate: r.reminderDate,
    idempotencyKey: r.idempotencyKey,
    status: 'sent',
  },
};

const r = $('Build reminder').item.json;
const message = String($json.error?.message || 'email provider error').slice(0, 300);
return {
  json: {
    loanId: r.loanId,
    reminderDate: r.reminderDate,
    idempotencyKey: r.idempotencyKey,
    status: 'failed',
    error: message,
  },
};

// Signs the reminder outcome; Convex stores it once per loan per day.
const crypto = require('crypto');
const secret = $vars.LENDLOOP_INBOUND_SECRET;
if (!secret) throw new Error('LENDLOOP_INBOUND_SECRET is not set');

const body = JSON.stringify($json);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'v1=' + crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.POST./n8n/reminders.${body}`)
  .digest('hex');
return { json: { body, timestamp, signature } };
